This fixes it for me:
~~~~
diff --git a/image-sixel.c b/image-sixel.c
index 1c93d7a7..6d18a978 100644
--- a/image-sixel.c
+++ b/image-sixel.c
@@ -595,7 +595,7 @@ sixel_print(struct sixel_image *si, struct sixel_image *map, size_t *size)
        tmplen = xsnprintf(tmp, sizeof tmp, "\033P0;%uq", si->p2);
        sixel_print_add(&buf, &len, &used, tmp, tmplen);

-       if (si->set_ra) {
+       if (0 && si->set_ra) {
                tmplen = xsnprintf(tmp, sizeof tmp, "\"1;1;%u;%u", si->ra_x,
                    si->ra_y);
                sixel_print_add(&buf, &len, &used, tmp, tmplen);
~~~~
The original image has 1;1;1184;0 as the RA and it is the same in the cropped image, but that seems wrong, the new image should be smaller...

This was added in 7a78cdf78c00370d4ff1eb2c7cb5678412de9002... @participant2 do you know what the problem is here?

It seems I misunderstood the coordinate system.  Currently we do:

ra_y = max(min(ra_y, psy) - poy, 0)

which would have been fine if psy and poy were actually a slice as per my comment, but they aren't, poy is an offset into the image and psy is the desired size.  Swapping the operations should fix the 0-height bug:

```diff
diff --git a/image-sixel.c b/image-sixel.c
index 1c93d7a7..5c800461 100644
--- a/image-sixel.c
+++ b/image-sixel.c
@@ -455,12 +455,12 @@ sixel_scale(struct sixel_image *si, u_int xpixel, u_int ypixel, u_int ox,
 	new->p2 = si->p2;

 	new->set_ra = si->set_ra;
-	/* clamp to slice end */
-	new->ra_x = si->ra_x < psx ? si->ra_x : psx;
-	new->ra_y = si->ra_y < psy ? si->ra_y : psy;
-	/* subtract slice origin */
+	/* subtract offset */
 	new->ra_x = new->ra_x > pox ? new->ra_x - pox : 0;
 	new->ra_y = new->ra_y > poy ? new->ra_y - poy : 0;
+	/* clamp to size */
+	new->ra_x = si->ra_x < psx ? si->ra_x : psx;
+	new->ra_y = si->ra_y < psy ? si->ra_y : psy;
 	/* resize */
 	new->ra_x = new->ra_x * xpixel / si->xpixel;
 	new->ra_y = new->ra_y * ypixel / si->ypixel;
```

This fixes it for me - we were only scrolling up if the image was greater than the screen size, not if it was exactly the same:
~~~~
--- a/screen-write.c
+++ b/screen-write.c
@@ -2339,7 +2339,7 @@ screen_write_sixelimage(struct screen_write_ctx *ctx, struct sixel_image *si,
        }

        sy = screen_size_y(s) - cy;
-       if (sy < y) {
+       if (sy <= y) {
                lines = y - sy + 1;
                if (image_scroll_up(s, lines) && ctx->wp != NULL)
                        ctx->wp->flags |= PANE_REDRAW;
